            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 2000,
                    quarterlyRevenue: 864,
                    quarterlyCosts: 1300,
                    ebitda: -436,
                    guides: 24,
                    certifiedGuides: 8,
                    envScore: 70,
                    reputation: 75,
                    laCaleraCap: 0.4,
                    compliancePaid: 0,
                    negotiationResult: 0,
                    auditPenalty: 0,
                    cashHistory: [],
                    ebitdaHistory: [],
                    envHistory: [],
                    repHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategy: 'expansion',
                    investment: 150,
                    negotiation: 'collaborative',
                    ecoTax: 25,
                    auditResponse: 'full_acceptance',
                    remediation: 20,
                    growthStrategy: 'organic',
                    sustainLevel: 'standard'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var stratEl = document.getElementById('strategySelect');
                if (stratEl) decisions.strategy = stratEl.value;
                var invEl = document.getElementById('investmentInput');
                if (invEl) decisions.investment = parseFloat(invEl.value) || 0;
                if (decisions.investment < 0 || decisions.investment > 500) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('investment_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var negEl = document.getElementById('negotiationSelect');
                if (negEl) decisions.negotiation = negEl.value;
                var taxEl = document.getElementById('ecoTaxInput');
                if (taxEl) decisions.ecoTax = parseFloat(taxEl.value) || 0;
                if (decisions.ecoTax < 0 || decisions.ecoTax > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('ecotax_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var audEl = document.getElementById('auditSelect');
                if (audEl) decisions.auditResponse = audEl.value;
                var remEl = document.getElementById('remediationInput');
                if (remEl) decisions.remediation = parseFloat(remEl.value) || 0;
                if (decisions.remediation < 0 || decisions.remediation > 60) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('remediation_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 4) {
                var grEl = document.getElementById('growthSelect');
                if (grEl) decisions.growthStrategy = grEl.value;
                var susEl = document.getElementById('sustainSelect');
                if (susEl) decisions.sustainLevel = susEl.value;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var revenue = ds.quarterlyRevenue;
            var costs = ds.quarterlyCosts;
            var envDelta = 0;
            var repDelta = 0;
            var guidesLost = 0;
            var narrative = '';

            if (period === 1) {
                var inv = Math.min(d.investment, ds.cash * 0.5);
                if (d.strategy === 'cost_reduction') {
                    guidesLost = Math.round(inv / 35);
                    costs = costs - (guidesLost * 45) - (inv * 0.4);
                    revenue = revenue * 0.95;
                    repDelta = -5;
                    envDelta = 2;
                    narrative = window.mySimulation.t('r1_cost') || 'Se redujo estructura de costos. Se perdieron guías experimentados.';
                } else if (d.strategy === 'expansion') {
                    revenue = revenue + (inv * 1.2);
                    costs = costs + (inv * 0.6);
                    envDelta = 5;
                    repDelta = 3;
                    narrative = window.mySimulation.t('r1_expansion') || 'Se abrieron rutas en nuevos parques nacionales.';
                } else if (d.strategy === 'urban_pivot') {
                    revenue = revenue + (inv * 0.8);
                    costs = costs + (inv * 0.5);
                    envDelta = -2;
                    repDelta = -3;
                    narrative = window.mySimulation.t('r1_urban') || 'Se lanzaron experiencias de aventura urbana en Medellín y Bogotá.';
                } else if (d.strategy === 'partnership') {
                    revenue = revenue + 250;
                    costs = costs + 80;
                    repDelta = -8;
                    envDelta = 3;
                    narrative = window.mySimulation.t('r1_partner') || 'Se negoció alianza con operador internacional. Se pierde independencia parcial.';
                }
                costs = costs + 31;
                ds.compliancePaid = 124;
                ds.cash = ds.cash - inv;
            } else if (period === 2) {
                var capGain = 0;
                var taxCost = d.ecoTax / 4;
                if (d.negotiation === 'collaborative') {
                    capGain = 0.225;
                    envDelta = 8 + Math.min(d.ecoTax / 10, 5);
                    repDelta = 6;
                    narrative = window.mySimulation.t('r2_collab') || 'Negociación colaborativa exitosa. Se obtuvieron 1.5 grupos/día en La Calera.';
                } else if (d.negotiation === 'aggressive') {
                    capGain = 0.3;
                    envDelta = 2;
                    repDelta = -4;
                    narrative = window.mySimulation.t('r2_aggr') || 'Se presionó al Ministerio. Se obtuvieron 2 grupos/día pero la relación quedó tensa.';
                } else {
                    capGain = 0.15;
                    envDelta = 5 + Math.min(d.ecoTax / 8, 4);
                    repDelta = 2;
                    narrative = window.mySimulation.t('r2_conc') || 'Enfoque concesivo. Mejora modesta en acceso, buena relación con Ministerio.';
                }
                ds.laCaleraCap = Math.min(ds.laCaleraCap + capGain, 1.0);
                var laCalRevenueGain = capGain * 1728;
                revenue = revenue + laCalRevenueGain;
                costs = costs + taxCost;
                ds.negotiationResult = capGain;
            } else if (period === 3) {
                var fine = 0;
                var remCost = d.remediation;
                if (d.auditResponse === 'full_acceptance') {
                    fine = 8;
                    envDelta = 12 + Math.round(d.remediation / 5);
                    repDelta = 8;
                    narrative = window.mySimulation.t('r3_accept') || 'Aceptación responsable. Ministerio valora transparencia. Concesión asegurada.';
                } else if (d.auditResponse === 'partial_contest') {
                    fine = 5;
                    envDelta = 5 + Math.round(d.remediation / 8);
                    repDelta = -3;
                    narrative = window.mySimulation.t('r3_partial') || 'Se contestó hallazgo mayor. Resultado mixto: multa reducida, relación deteriorada.';
                } else {
                    fine = 2;
                    envDelta = -8;
                    repDelta = -12;
                    narrative = window.mySimulation.t('r3_contest') || 'Se contestaron todos los hallazgos. Ministerio considera falta de cooperación. Riesgo elevado.';
                }
                costs = costs + fine + remCost;
                ds.auditPenalty = fine;
            } else if (period === 4) {
                var growthMult = 1.0;
                var costMult = 1.0;
                if (d.growthStrategy === 'organic') {
                    growthMult = 1.15;
                    costMult = 1.05;
                    repDelta = 5;
                } else if (d.growthStrategy === 'aggressive_growth') {
                    growthMult = 1.35;
                    costMult = 1.2;
                    repDelta = -2;
                } else {
                    growthMult = 1.25;
                    costMult = 1.08;
                    repDelta = 3;
                }
                revenue = revenue * growthMult;
                costs = costs * costMult;

                if (d.sustainLevel === 'minimum') {
                    envDelta = 3;
                    costs = costs + 10;
                } else if (d.sustainLevel === 'standard') {
                    envDelta = 12;
                    costs = costs + 40;
                    repDelta = repDelta + 8;
                } else {
                    envDelta = 25;
                    costs = costs + 80;
                    repDelta = repDelta + 15;
                    revenue = revenue * 1.1;
                }
                narrative = window.mySimulation.t('r4_result') || 'Plan estratégico presentado al Board.';
            }

            revenue = Math.round(revenue);
            costs = Math.round(costs);
            var ebitda = revenue - costs;
            ds.quarterlyRevenue = revenue;
            ds.quarterlyCosts = costs;
            ds.ebitda = ebitda;
            ds.cash = Math.round(ds.cash + ebitda);
            ds.guides = Math.max(6, ds.guides - guidesLost);
            ds.envScore = Math.max(0, Math.min(100, ds.envScore + envDelta));
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + repDelta));

            ds.cashHistory.push(ds.cash);
            ds.ebitdaHistory.push(ebitda);
            ds.envHistory.push(ds.envScore);
            ds.repHistory.push(ds.reputation);

            // platform score: same composite as getPerformanceSummary, 25 if cash positive plus env times 0.4 plus reputation times 0.35, already 0 to 100
            var compositeVal = Math.round((ds.cash > 0 ? 25 : 0) + (ds.envScore * 0.4) + (ds.reputation * 0.35));
            var overallScoreVal = Math.max(0, Math.min(100, compositeVal));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScoreVal });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            if (state.currentPeriod >= (state.maxPeriods || this.ROUNDS.length)) { var selfC = this; setTimeout(function() { try { selfC._renderCompletion(state); } catch (e) {} }, 0); }

            return {
                period: period,
                revenue: revenue,
                costs: costs,
                ebitda: ebitda,
                cash: ds.cash,
                guides: ds.guides,
                envScore: ds.envScore,
                reputation: ds.reputation,
                narrative: narrative
            };
        }

